package com.enterprise.procurement.admin.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper; import com.baomidou.mybatisplus.extension.plugins.pagination.Page; import com.enterprise.procurement.admin.dto.AdminDtos.*; import com.enterprise.procurement.admin.entity.*; import com.enterprise.procurement.admin.mapper.*; import org.springframework.data.redis.core.StringRedisTemplate; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Duration; import java.util.*;

@Service public class AdminService {
 private final SysUserMapper users; private final DepartmentMapper departments; private final RoleMapper roles; private final PermissionMapper permissions; private final MenuMapper menus; private final SysConfigMapper configs; private final RelationMapper relations; private final PasswordEncoder encoder; private final StringRedisTemplate redis;
 public AdminService(SysUserMapper u,DepartmentMapper d,RoleMapper r,PermissionMapper p,MenuMapper m,SysConfigMapper c,RelationMapper rel,PasswordEncoder e,Optional<StringRedisTemplate> rt){users=u;departments=d;roles=r;permissions=p;menus=m;configs=c;relations=rel;encoder=e;redis=rt.orElse(null);}
 private void evict(String... keys){if(redis!=null)for(String k:keys)redis.delete(k);}
 public Page<SysUser> userPage(UserQuery q){int p=q.page()==null?1:q.page(),s=q.size()==null?20:q.size(); return users.selectPage(new Page<>(p,s),new LambdaQueryWrapper<SysUser>().and(q.keyword()!=null&&!q.keyword().isBlank(),w->w.like(SysUser::getUsername,q.keyword()).or().like(SysUser::getNickname,q.keyword())).eq(q.status()!=null,SysUser::getStatus,q.status()).eq(q.departmentId()!=null,SysUser::getDepartmentId,q.departmentId()).orderByDesc(SysUser::getId));}
 public UserVO user(Long id){SysUser u=users.selectById(id); if(u==null) return null; return vo(u);}
 public UserVO byUsername(String username){SysUser u=users.findByUsername(username); return u==null?null:vo(u);}
 private UserVO vo(SysUser u){return new UserVO(u.getId(),u.getUsername(),u.getNickname(),u.getPhone(),u.getEmail(),u.getDepartmentId(),u.getStatus(),users.roleCodes(u.getId()),users.permissionCodes(u.getId()));}
 @Transactional public UserVO create(UserCreate x){SysUser u=new SysUser();u.setUsername(x.username());u.setPassword(encoder.encode(x.password()));u.setNickname(x.nickname());u.setPhone(x.phone());u.setEmail(x.email());u.setDepartmentId(x.departmentId());u.setStatus(x.status()==null?1:x.status());users.insert(u);if(x.roleIds()!=null&&!x.roleIds().isEmpty())relations.insertUserRoles(u.getId(),x.roleIds());return vo(u);}
 @Transactional public UserVO update(Long id,UserUpdate x){SysUser u=users.selectById(id);if(u==null)return null;if(x.nickname()!=null)u.setNickname(x.nickname());if(x.phone()!=null)u.setPhone(x.phone());if(x.email()!=null)u.setEmail(x.email());if(x.departmentId()!=null)u.setDepartmentId(x.departmentId());if(x.status()!=null)u.setStatus(x.status());if(x.password()!=null&&!x.password().isBlank())u.setPassword(encoder.encode(x.password()));users.updateById(u);if(x.roleIds()!=null){relations.deleteUserRoles(id);if(!x.roleIds().isEmpty())relations.insertUserRoles(id,x.roleIds());}evict("auth:permissions:"+id);return vo(u);}
 @Transactional public boolean deleteUser(Long id){relations.deleteUserRoles(id);return users.deleteById(id)>0;}
 public List<Department> departmentList(){if(redis!=null){String v=redis.opsForValue().get("admin:departments");if(v!=null&&!v.isBlank()){}}List<Department> out=departments.selectList(new LambdaQueryWrapper<Department>().orderByAsc(Department::getId));if(redis!=null)redis.opsForValue().set("admin:departments",String.valueOf(out.size()),Duration.ofMinutes(10));return out;}
 @Transactional public Department saveDepartment(Long id,DepartmentRequest x){Department d=id==null?new Department():departments.selectById(id);d.setName(x.name());d.setParentId(x.parentId());d.setStatus(x.status()==null?1:x.status());if(id==null)departments.insert(d);else departments.updateById(d);evict("admin:departments");return d;}
 public boolean deleteDepartment(Long id){boolean ok=departments.deleteById(id)>0;evict("admin:departments");return ok;}
 public List<Role> roleList(){return roles.selectList(new LambdaQueryWrapper<>());}
 @Transactional public Role saveRole(Long id,RoleRequest x){Role r=id==null?new Role():roles.selectById(id);r.setCode(x.code());r.setName(x.name());if(id==null)roles.insert(r);else roles.updateById(r);if(x.permissionIds()!=null){relations.deleteRolePermissions(r.getId());if(!x.permissionIds().isEmpty())relations.insertRolePermissions(r.getId(),x.permissionIds());}evict("admin:permissions");return r;}
 public boolean deleteRole(Long id){return roles.deleteById(id)>0;}
 public List<Permission> permissionList(){return permissions.selectList(new LambdaQueryWrapper<>());}
 public Permission savePermission(Long id,PermissionRequest x){Permission p=id==null?new Permission():permissions.selectById(id);p.setCode(x.code());p.setName(x.name());if(id==null)permissions.insert(p);else permissions.updateById(p);evict("admin:permissions");return p;}
 public boolean deletePermission(Long id){return permissions.deleteById(id)>0;}
 public List<Menu> menuList(){return menus.selectList(new LambdaQueryWrapper<Menu>().orderByAsc(Menu::getSortOrder));}
 public Menu saveMenu(Long id,MenuRequest x){Menu m=id==null?new Menu():menus.selectById(id);m.setName(x.name());m.setParentId(x.parentId());m.setPath(x.path());m.setIcon(x.icon());m.setPermissionCode(x.permissionCode());m.setSortOrder(x.sortOrder());m.setStatus(x.status()==null?1:x.status());if(id==null)menus.insert(m);else menus.updateById(m);evict("admin:menus");return m;}
 public boolean deleteMenu(Long id){return menus.deleteById(id)>0;}
 public List<SysConfig> configList(){return configs.selectList(new LambdaQueryWrapper<>());}
 public SysConfig saveConfig(Long id,ConfigRequest x){SysConfig c=id==null?new SysConfig():configs.selectById(id);c.setConfigKey(x.configKey());c.setConfigValue(x.configValue());c.setDescription(x.description());if(id==null)configs.insert(c);else configs.updateById(c);return c;}
 public boolean deleteConfig(Long id){return configs.deleteById(id)>0;}
}
